#!/usr/bin/env python3
"""Render the build route from docs/build/data.json. No runtime dependencies.

Update prices in data.json, then run python3 scripts/render-build-guides.py.
The budget and shopping pages also read this same data in the browser.
"""
from pathlib import Path
from html import escape as E
import json

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'docs/build'
D=json.loads((OUT/'data.json').read_text())
REPO='https://github.com/kissqy/Microduck-kissqy'
FILE=REPO+'/blob/main/'
RAW=REPO+'/raw/refs/heads/main/'
IMAGE=REPO+'/releases/download/public-image-r1/microduck-zero3w-0.15.1-R1.img.xz'
CONSOLE=RAW+'release-assets/Microduck-Console-R17-V167.zip'
PRINTS=RAW+'hardware/3d-print-frankenduck/Microduck-Print-FrankenDuck-20261015.rar'
ROUTES=[('budget.html','花多少钱','我要花多少钱？','先看各方案合计，再看费用明细。'),('shopping.html','买什么','我要买什么？','按规格、数量与链接，备齐一只鸭子。'),('assembly.html','怎么装','我要怎么装？','跟着部位和步骤，装好结构与接线。'),('start.html','走起来','我要让鸭子走起来','使用现成模型，完成刷机、标定与行走。')]
money=lambda cents:'¥'+f'{cents/100:,.2f}'
BODY=sum(x['subtotalCents'] for x in D['items'])
BOARDS=sum(x['subtotalCents'] for x in D['boards'])
BASE=BODY+BOARDS
DIY_MIN=BODY+D['diyMaterialsMinCents']+D['diyToolsMinCents']
DIY_MAX=BODY+D['diyMaterialsMaxCents']+D['diyToolsMaxCents']
QUOTED_COUNT=len(D['items'])+len(D['boards'])
REQUIRED_COUNT=QUOTED_COUNT+len(D['unpriced'])

def link(url,label,cls=''):
 return f'<a href="{E(url,quote=True)}"'+(f' class="{cls}"' if cls else '')+'>'+label+'</a>'

def actions(*buttons):return '<div class="actions">'+''.join(buttons)+'</div>'

def next_page(index):
 if index>=3:return '<section class="page-next"><div><small>完成第一次行走后</small><strong>继续熟悉日常操作</strong><p>摄像头、声音、手柄动作与关机，在中控教程里继续看。</p></div>'+link('../console-guide.html#buttons','打开中控使用教程 →','btn primary')+'</section>'
 f,_,title,desc=ROUTES[index+1]
 return '<section class="page-next"><div><small>下一步 · '+str(index+2).zfill(2)+'</small><strong>'+title+'</strong><p>'+desc+'</p></div>'+link(f,'继续下一步 →','btn primary')+'</section>'

def shell(filename,title,description,content,index=-1):
 nav=''.join(f'<a href="{f}"'+(' aria-current="page"' if index==i else '')+f'><b>{i+1:02}</b><span>{label}</span></a>' for i,(f,label,_,_) in enumerate(ROUTES))
 return f'''<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0d1113"><title>{E(title)} · Microduck 飞特版</title><meta name="description" content="{E(description,quote=True)}"><link rel="canonical" href="https://kissqy.github.io/Microduck-kissqy/build/{filename if filename!='index.html' else ''}"><link rel="stylesheet" href="build.css?v=20261027-detail-links"></head>
<body><header class="site-header"><div class="header-main"><a class="brand" href="./"><svg viewBox="0 0 40 40" aria-hidden="true"><rect width="40" height="40" rx="11" fill="#c1f577"/><path d="M9 23h9V11h12v11h-7v9H9z" fill="#24311e"/></svg>microduck <small>从零到第一次行走</small></a><nav class="header-links" aria-label="其他入口"><a href="{REPO}">项目首页 ↗</a><a href="../console-guide.html">中控教程</a></nav></div><nav class="route-nav" aria-label="新手四步">{nav}</nav></header>
<main class="wrap">{content}<footer class="site-footer"><div>Microduck 飞特版 · kissqy<br>使用配套现成动作模型，日常操作使用机器人中控。</div><div><a href="{FILE}docs/MICRODUCK-FAQ.md">常见问题</a> · <a href="{FILE}docs/assets/purchase-wechat-qr.jpg">联系作者</a> · <a href="{FILE}microduck-hd1910/LICENSE">分项许可</a></div></footer></main><script type="module" src="build.js?v=20261027-detail-links"></script></body></html>'''

def head(number,title,lead,badge=''):
 return '<section class="page-head"><p class="eyebrow">'+number+'</p><div class="head-line"><div><h1>'+title+'</h1><p class="lead">'+lead+'</p></div>'+(f'<span class="badge">{badge}</span>' if badge else '')+'</div></section>'

cards=''.join(f'<a class="route-card" href="{f}"><b>{i+1:02}</b><h2>{title}</h2><p>{desc}</p><span>进入这一步 →</span></a>' for i,(f,_,title,desc) in enumerate(ROUTES))
overview=head('MICRODUCK / BUILD','从零件，到第一步。','按预算、采购、装配、开机行走的顺序做。项目提供系统镜像、中文机器人中控与现成动作模型。','使用现成模型，无须自己训练')+f'<div class="route-grid">{cards}</div>'
overview+='''<section class="panel"><h2>已经做了一部分？从当前进度继续</h2><div class="pill-row"><a href="shopping.html">准备采购</a><a href="assembly.html">零件已买齐</a><a href="start.html#flash">结构已经装好</a><a href="start.html#network">已刷好镜像</a><a href="start.html#calibration">已连接中控</a></div></section><a href="../one-leg-balance.html"><img class="feature-photo" src="../assets/community-one-leg-banner.webp" alt="Microduck 实机与单脚独立成果，点击观看视频" width="1586" height="992"></a><section class="panel"><h2>这条路线会用到什么</h2><div class="complete-grid"><div><strong>完整制作资料</strong><p>采购链接、打印文件、板卡说明和装配参考。</p></div><div><strong>中文机器人中控</strong><p>连接、标定、观察反馈、操作与维护。</p></div><div><strong>配套现成模型</strong><p>先体验行走和已有动作，再探索更多玩法。</p></div></div></section>'''
(OUT/'index.html').write_text(shell('index.html','从零复刻路线','Microduck 从预算、采购、装配到第一次行走，使用配套现成模型，无须自己训练。',overview))

def plan(identifier,title,total,extra,desc,target,featured=False):
 return f'<article class="plan'+(' featured' if featured else '')+f'" data-plan="{identifier}"><h2>{title}</h2><p class="amount'+(' range' if identifier=='diy' else '')+f'" data-price>{total}</p><p class="pending" data-pending>{extra}</p><p class="small">{desc}</p>'+link(target,'看采购明细 →')+'</article>'

budget=head('01 / BUDGET','我要花多少钱？','先按有没有打印机选择，再看自己打印、找人代打或买机器的预算。','默认路线 · 购买成品板')
budget+='<div class="plan-grid">'+plan('own','有打印机 · 自己打印',money(BASE),'＋打印耗材、待补配件与运费','已有打印机，设备费不重复算。基础采购含成品 HAT／IMU。','shopping.html',True)+plan('service','无打印机 · 找人代打','待填代打报价','填入整套代打报价后计算；无需购买打印机。','基础采购 '+money(BASE)+'＋整套代打费；硬质件与 TPU 一并询价。','shopping.html?printing=service')+plan('buy-printer','无打印机 · 买机器自己打',money(BASE+D['printerReferenceCents']),'＋打印耗材、待补配件与运费','基础采购 '+money(BASE)+'＋打印机设备参考 '+money(D['printerReferenceCents'])+'；设备价格可改。','shopping.html?printing=buy-printer')+'</div>'
budget+='<p class="price-note"><strong>上面三档按打印机条件区分，默认均购买成品板。</strong>含作者整套配置、手柄、32GB TF 卡及参考备料；打印、HUB、读卡器等未完整报价的项目和运费需要补齐。价格来自历史订单与作者定价，M2×5 螺丝的历史优惠价为 0 元。</p>'
budget+='''<section class="panel" id="calculator"><h2>把自己的补充费用填进来</h2><p class="small">单位：元。设备费只用于“买机器自己打”，代打费只用于“找人代打”，耗材费用于两种自打方案。已有并可复用的其他项目填 0，还没报价的留空。</p><div class="field-grid"><label>自己打印：耗材费<input type="number" min="0" max="1000000" step="0.01" inputmode="decimal" placeholder="填实际耗材预算" data-cost="ownPrint"><small>用于“有打印机”和“买机器”两种自打方案</small></label><label>找人代打：整套报价<input type="number" min="0" max="1000000" step="0.01" inputmode="decimal" placeholder="填代打商的整套报价" data-cost="printService"><small>硬质件与 TPU 部分一并询价</small></label><label>买机器自己打：打印机设备费<input type="number" min="0" max="1000000" step="0.01" inputmode="decimal" value="3500" placeholder="填打印机实际购买价格" data-cost="printer"><small>参考预填 ¥3500，仅计入买机器这一档</small></label><label>待补配件合计<input type="number" min="0" max="1000000" step="0.01" inputmode="decimal" placeholder="HUB、读卡器、工具等" data-cost="extras"><small>按下方待补清单核对；已含的不重复算</small></label><label>运费与零星费用<input type="number" min="0" max="1000000" step="0.01" inputmode="decimal" placeholder="填自己的预留" data-cost="shipping"><small>可包含历史优惠结束后的差价</small></label></div><p class="budget-state" id="budget-state">打印机设备费按参考 ¥3500 预填，可改为实际报价；代打未报价时不展示总额。其他待补费用另计。</p><div class="actions"><button class="btn" type="button" id="reset-budget">恢复默认预算</button><a class="btn" href="shopping.html#unpriced">查看待补项目 →</a></div></section>'''
totals={g['id']:sum(i['subtotalCents'] for i in D['items']+D['boards'] if i['group']==g['id']) for g in D['groups']}
rows=''.join(f'<tr><td>{g["name"]}</td><td class="amount">{money(totals[g["id"]])}</td></tr>' for g in D['groups'])
budget+='<div class="two-col"><section class="panel"><h2>成品板方案，钱花在哪里</h2><div class="table-wrap"><table class="breakdown"><thead><tr><th>分类</th><th class="amount">参考小计</th></tr></thead><tbody>'+rows+f'<tr><td>已列价合计</td><td class="amount">{money(BASE)}</td></tr></tbody></table></div><p class="source-line">预算与采购明细共用同一份价格数据。</p></section><section class="panel"><h2>这些费用还要核对</h2><ul><li>打印件：自打算耗材，代打按整套报价。</li><li>HUB、电池接入、读卡器和常规手工具：已有可复用；32GB TF 卡已按 ¥39.90 计入。</li><li>总电源电容：HUB 已配套安装时不重复购买。</li><li>普通电脑、人工、运费与损耗未包含在基础采购表内。</li></ul>'+link('shopping.html#unpriced','逐项看待补清单 →')+'</section></div>'
budget+=f'<details><summary>可选：自己焊 HAT／IMU，需要多少钱？</summary><p>自焊时不重复购买成品板 ¥218。首批板卡材料参考 {money(D["diyMaterialsMinCents"])}–{money(D["diyMaterialsMaxCents"])}，另预留工具与耗材 ¥800–1000。已有工具可复用。</p><p>参考本体＋自焊材料＋基础工具合计为 {money(DIY_MIN)}–{money(DIY_MAX)}，仍需另计所选打印方式与待报价项目。</p><p>'+link(FILE+'docs/BUILD-TOOLS.md','查看焊接工具与耗材')+' · '+link(FILE+'hardware/README.md#制作成本','查看 PCB 材料成本')+'</p></details>'+next_page(0)
budget=budget.replace('value="3500"',f'value="{D["printerReferenceCents"]/100:g}"')
(OUT/'budget.html').write_text(shell('budget.html','我要花多少钱','按有无打印机比较 Microduck 自己打印、找人代打、买机器自己打的费用，单独计算设备费与打印费。',budget,0))

def purchase_row(item):
 spec=E(item['spec']);note=E(item['note'])
 return f'<tr><td class="item-name"><label class="prepared-label"><input type="checkbox" data-prepared="{item["id"]}" aria-label="{E(item["name"],quote=True)} 已备齐"><span><strong>{E(item["name"])}</strong><span class="spec">{spec}<br>{note}</span></span></label></td><td class="quantity" data-label="参考采购量">{item["quantity"]} {E(item["unit"])}</td><td class="amount" data-label="历史单价">¥{E(item["unitQuote"])}</td><td class="amount" data-label="小计">{money(item["subtotalCents"])}</td><td class="buy">'+link(item['url'],'购买 ↗')+'</td></tr>'

shop=head('02 / SHOPPING','我要买什么？','下面就是成品板路线的采购清单：按型号、数量和购买入口准备。','完整参考配置 · 含备料')
shop+='<section class="panel" id="printing-choice" hidden><span class="badge">当前采购路线</span><h2 id="printing-choice-title" style="margin-top:12px"></h2><p id="printing-choice-description"></p><ul id="printing-choice-items"></ul><div class="actions"><a class="btn primary" href="#boards">查看基础零件清单 ↓</a><a class="btn" href="'+FILE+'hardware/3d-print-frankenduck/README.md">查看打印文件与材料说明 ↗</a><a class="btn" id="printing-choice-quote" href="budget.html#calculator">返回预算 →</a></div></section>'
shop+=f'<div class="summary-bar"><div><small>{QUOTED_COUNT} 项已列价采购参考</small><strong data-base-total>{money(BASE)}</strong><small>另有打印、HUB、读卡器等待报价项目</small></div>'+link('budget.html','返回预算明细','btn')+'</div>'
shop+=f'<div class="check-status"><span id="prepared-count">0 / {REQUIRED_COUNT} 项已备齐</span><button id="reset-prepared" type="button">重置勾选</button></div><div class="progress" aria-hidden="true"><span id="prepared-bar"></span></div>'
shop+='<p class="price-note">勾选自己已买到或可复用的物品，进度只保存在这台设备。下表保留作者的历史采购数量，包含整包备料；相同规格的实际装机数量按打印件与走线核对。</p>'
shop+='<nav class="toc" aria-label="采购分类">'+''.join(link('#'+g['id'],g['name']) for g in D['groups'])+link('#unpriced','待补项目')+link('#optional','选配')+'</nav>'
for group in D['groups']:
 shop+=f'<section class="purchase-group" id="{group["id"]}"><h2>{group["name"]} <span class="small">{money(totals[group["id"]])}</span></h2>'
 shop+='<div class="table-wrap"><table class="shopping-table"><thead><tr><th>物品与指定规格</th><th>参考采购量</th><th class="amount">历史单价</th><th class="amount">小计</th><th>购买入口</th></tr></thead><tbody>'+''.join(purchase_row(item) for item in D['boards']+D['items'] if item['group']==group['id'])+'</tbody></table></div></section>'
shop+='<section class="panel" id="unpriced"><h2>还要补齐这些项目</h2><p class="small">下面尚无完整报价，没有假设为免费；取得报价后填回预算页。已有并可复用的项目也可以勾选。</p><div class="unpriced-list">'
for item in D['unpriced']:
 shop+=f'<article class="unpriced-item"><label><input type="checkbox" data-prepared="{item["id"]}"><span>{E(item["name"])}</span></label><p>{E(item["spec"])}</p>'+link(item['url'],'看规格或联系入口 ↗')+'</article>'
shop+='</div></section>'
shop+='<section class="panel" id="optional"><h2>选配：装滑轮时再买</h2><p>623ZZ 轴承，款式“623 内3外10厚4”，参考采购 8 只，历史商品小计 ¥12。此项不计入基础采购合计。</p>'+actions(link(D['optional'][0]['url'],'查看滑轮轴承 ↗','btn'),link(FILE+'hardware/3d-print-frankenduck/README.md','查看滑轮与脚掌打印件','btn'))+'</section>'
shop+='<details id="diy"><summary>想自己焊 HAT／IMU：材料与工具在这里</summary><p>默认清单购买成品板。自焊时不重复购买成品 HAT／IMU，按 PCB 用料另购材料，并准备贴装、焊接与 IMU 烧录工具。</p><p>'+link(FILE+'hardware/README.md#采购清单','PCB 详细 BOM 与采购表')+' · '+link(FILE+'docs/BUILD-TOOLS.md','焊接工具与耗材')+' · '+link(FILE+'hardware/IMU-FIRMWARE.md','自焊 IMU 烧录指南')+'</p></details>'
shop+='<section class="panel"><h2>准备好了再开始装</h2><p>确认打印件、舵机、主控、HAT／IMU、电池接入、轴承螺丝和匹配线材都已到手。按电池仓方案补齐 HUB。</p><p class="small">未勾选的已列价项目参考合计：<strong id="remaining-total">'+money(BASE)+'</strong>；待报价项目另计。</p>'+actions('<button class="btn" id="print-list" type="button">打印这份清单</button>')+'</section>'+next_page(1)
(OUT/'shopping.html').write_text(shell('shopping.html','我要买什么','Microduck 成品板路线的完整参考采购清单：型号、数量、价格、购买链接和待补项目。',shop,1))

assembly=head('03 / ASSEMBLY','我要怎么装？','先看整机结构，再按部位组装，最后接线和核对。','实物图＋按部位查看 3D')
assembly+='''<div class="instruction-grid"><section class="panel" style="margin-top:0"><h2>按这六步完成装配</h2><nav class="toc" aria-label="装配步骤"><a href="#prepare">01 打印与准备</a><a href="#legs">02 两条腿</a><a href="#body">03 躯干与电池仓</a><a href="#head">04 头颈与板卡</a><a href="#wiring">05 接线</a><a href="#check">06 上电前核对</a></nav><div class="actions"><a class="btn primary" href="#prepare">从第一步开始 →</a><a class="btn" href="../assembly.html#wiring-guide">先看接线总图</a></div><p class="small" style="margin-top:16px">每一步都提供需要的部件、对应 3D 视角和完成检查点。3D 可旋转、开盖及爆炸展开。</p></section><figure><img src="../assets/build-robot.jpg" alt="作者完成装配的 Microduck 飞特机器人鸭" width="1536" height="1152"><figcaption>作者实机外观。安装时按自己的打印件、接口版本和机械位置核对。</figcaption></figure></div>'''
assembly+='<section class="chapter" id="prepare"><div class="chapter-head"><span class="number">01</span><h2>准备打印件、舵机与工具</h2></div><p class="needed">需要：打印包、15 只 HD1910、轴承、螺丝、常规装配工具。</p><ol><li>下载并解压缝合怪版打印包：36 个 STL、1 个 3MF 参考摆盘项目。文件数量不是装机数量。</li><li>电池仓选一份：需要 HUB 组合结构时选“电池仓_M2.5螺丝_HUB组合.stl”；另有“电池仓_卡扣加厚.stl”。</li><li>第 5 盘为 TPU 部件，包含左右脚底和滑轮。打印前切换实际 TPU 材料配置。</li><li>正式装连接件前，核对各舵机 ID 与装配参考角度。未装配舵机的居中操作见中控教程；已经装好的结构按本机逐轴标定。</li></ol>'+actions(link(PRINTS,'下载完整打印包','btn primary'),link(FILE+'hardware/3d-print-frankenduck/README.md','看摆盘与打印说明','btn'),link('../console-guide.html#calibration','舵机准备与标定说明','btn'))+'<p class="done">完成标准：打印件分类齐全，电池仓版本已确定，舵机与对应 ID 已核对。</p><a class="step-next" href="#legs">下一步：组装两条腿 ↓</a></section>'
assembly+='<section class="chapter" id="legs"><div class="chapter-head"><span class="number">02</span><h2>两条腿：先分清左右和编号</h2></div><p class="needed">需要：左右腿打印件、10–14／20–24 舵机、对应轴承、脚掌与螺丝。</p><p>左右按鸭子自身：右腿从髋到踝为 <strong>10、11、12、13、14</strong>，左腿为 <strong>20、21、22、23、24</strong>。正面观察时，与屏幕左右相反。</p><ol><li>先按腿部分好外壳、连接件、加强板、踝支架和脚掌。</li><li>打开对应腿的 3D 视角，旋转查看关节连接方向；爆炸展开可看打印件的相互位置。</li><li>按实际打印件的孔位与安装图选择螺丝长度，逐段装好；软质脚底使用对应 TPU 件。</li></ol>'+actions(link('../assembly.html?part=left','查看左腿 20–24','btn primary'),link('../assembly.html?part=right','查看右腿 10–14','btn'))+'<p class="done">完成标准：两腿 ID 与方向对应，连接件固定，活动时无线束夹压或明显机械干涉。</p><a class="step-next" href="#body">下一步：躯干与电池仓 ↓</a></section>'
assembly+='<section class="chapter" id="body"><div class="chapter-head"><span class="number">03</span><h2>躯干、电池仓、HUB 与 IMU</h2></div><p class="needed">需要：躯干打印件、已选电池仓、HUB、独立 IMU、电池接入配件。</p><ol><li>连接两侧髋部与躯干结构，固定电池仓。</li><li><strong>HUB 平放在 10、20 舵机上方，长边沿机身前后方向。</strong>电源输入及分线端子按实板确认。</li><li><strong>IMU 贴合电池仓背部的主安装板面，J1 总线端子朝上。</strong>核对背板与横条位置后固定。</li><li>电池接入方式按选用的电池仓完成，暂不带电插拔总线。</li></ol>'+actions(link('../assembly.html?component=hub','放大查看 HUB','btn primary'),link('../assembly.html?component=imu','放大查看 IMU 与电池仓','btn'))+'<p class="done">完成标准：电池仓和板卡固定可靠，IMU 贴合主背板、端子朝上，HUB 安装方向正确。</p><a class="step-next" href="#head">下一步：头颈与板卡 ↓</a></section>'
assembly+='<section class="chapter" id="head"><div class="chapter-head"><span class="number">04</span><h2>头颈与鸭脸内部</h2></div><p class="needed">需要：30–34 舵机、头颈打印件、ZERO 3W、HAT、摄像头及配套外围。</p><ol><li>按 30、31、32、33、34 的位置核对颈部、头部和嘴部，安装对应连接件与壳体。</li><li>ZERO 3W 与 HAT 安装在鸭脸内部。先对准 HAT 底部 J4 的 40 针配对座，核对 1 脚和朝向。</li><li>安装摄像头与所需外围，整理线束，给开盖与关节活动留出空间。</li><li>确认线束不被头盖压住后再合盖。</li></ol>'+actions(link('../assembly.html?part=head','查看头颈结构','btn'),link('../assembly.html?component=hat','开盖查看 HAT','btn primary'),link('../assembly.html?component=zero','开盖查看 ZERO 3W','btn'))+'<p class="done">完成标准：HAT／ZERO 配对座方向正确，摄像头与外围固定，头颈活动时无线束拉扯。</p><a class="step-next" href="#wiring">下一步：接线 ↓</a></section>'
assembly+='<section class="chapter" id="wiring"><div class="chapter-head"><span class="number">05</span><h2>先对连接关系，再对端子信号</h2></div><p class="needed">需要：与板卡版本匹配的三芯线束、电池供电线、总电源缓冲电容。</p><div class="table-wrap"><table><thead><tr><th>支路</th><th>连接顺序</th></tr></thead><tbody><tr><td>头颈到躯干</td><td>HAT → 34 → 33 → 32 → 31 → 30 → HUB</td></tr><tr><td>右腿</td><td>HUB → 10 → 11 → 12 → 13 → 14</td></tr><tr><td>左腿</td><td>HUB → 20 → 21 → 22 → 23 → 24</td></tr><tr><td>IMU</td><td>HUB → IMU 总线端子 J1</td></tr><tr><td>供电</td><td>电池 → HUB CN1；核对正极／GND</td></tr></tbody></table></div><p>每条总线核对 <strong>GND、电源、DATA</strong>。颜色用于辨认示意，不替代实物针号与信号名；各板接口编号可能不同。</p><p>在总电源输入侧使用 1000 µF／16 V 缓冲电容；HUB 已装同规格电容时按实板确认。自焊 IMU 还需要单独烧录 STM32 FT6 固件。</p>'+actions(link('../assembly.html#wiring-guide','端子与信号对照总图','btn primary'),link(FILE+'docs/ASSEMBLY-NOTES.md','供电与接线注意事项','btn'),link(FILE+'hardware/IMU-FIRMWARE.md','自焊 IMU 烧录','btn'))+'<p class="done">完成标准：线束插入实际端子，供电极性与电容极性已核对，关节活动范围内不夹线。</p><a class="step-next" href="#check">下一步：上电前核对 ↓</a></section>'
assembly+='<section class="chapter" id="check"><div class="chapter-head"><span class="number">06</span><h2>装完先核对，再刷机连接</h2></div><ul><li>舵机位置与 ID 对应，左右腿分清，机械连接固定。</li><li>HAT／ZERO 排针及板卡线束方向正确，电池正负极和电容极性确认。</li><li>IMU 已固定，头盖及各关节不会压线、卡线。</li><li>已准备 TF 卡、读卡器和电脑，下一步使用配套系统镜像与机器人中控。</li></ul><p class="done">装配完成后仍要做本机舵机与 IMU 标定，再执行 HOME 与行走。</p></section>'+next_page(2)
(OUT/'assembly.html').write_text(shell('assembly.html','我要怎么装','Microduck 按部位组装与接线步骤，配合实物图、舵机编号、开盖与爆炸 3D 参考。',assembly,2))

start=head('04 / FIRST WALK','让鸭子走出第一步。','使用发布包里的现成动作模型，按下面六步完成。','无须自己训练')
start+='''<nav class="toc" aria-label="首次行走流程"><a href="#flash">01 刷镜像</a><a href="#network">02 配网查 IP</a><a href="#connect">03 连接中控</a><a href="#calibration">04 标定</a><a href="#home">05 HOME 检查</a><a href="#walk">06 保持与行走</a></nav><div class="note-box"><p>这一步使用<strong>机器人中控</strong>。系统镜像已预装机器人服务与运动模型；在电脑上完整解压并启动中控后连接自己的 ZERO。</p></div>'''
start+='<section class="chapter" id="flash"><div class="chapter-head"><span class="number">01</span><h2>下载并刷入配套系统镜像</h2></div><p class="needed">需要：已装配机器人、TF 卡与读卡器、电脑。</p>'+actions(link(IMAGE,'下载系统镜像 R1 · .img.xz','btn primary'),link('https://imager.armbian.com/','下载 Armbian Imager ↗','btn'),link(FILE+'docs/releases/public-image-r1.md','镜像说明与校验','btn'))+'<ol><li>打开 Armbian Imager，选择下载的自定义镜像与正确的 TF 卡。</li><li>直接写入 <code>.img.xz</code>，不用先手动解压；确认目标是要刷写的 TF 卡。</li><li>完成后将卡插入 Radxa ZERO 3W，上电等待首次初始化。</li></ol><p class="done">正常结果：首次启动后，手机能找到机器人热点 Microduck-kissqy。</p><details><summary>没有看到热点？</summary><p>先核对供电、TF 卡刷写是否完成及首次启动初始化，再按镜像说明排查。当前步骤尚不要求知道机器人的家庭网络 IP。</p></details><a class="step-next" href="#network">下一步：配网与查 IP ↓</a></section>'
start+='''<section class="chapter" id="network"><div class="chapter-head"><span class="number">02</span><h2>手机配网，再从路由器找到 IP</h2></div><ol><li>手机连接热点 <code>Microduck-kissqy</code>，热点密码 <code>12345678</code>。</li><li>打开弹出的配网页面；没弹出时访问下面的地址。</li><li>填写家里的 <strong>5 GHz Wi-Fi</strong>，并设置自己的 radxa 系统登录密码。</li><li>手机和电脑接回同一个家庭路由器，在路由器 App／后台的在线设备列表找到机器人，记下它的 IPv4 地址。</li></ol><div class="address"><span class="small">连接机器人热点时的配网入口</span><br><code>http://10.42.0.1:8088</code></div><div class="address"><span class="small">假设路由器查到 IP 为 192.168.1.123，中控填写</span><br><code>radxa@192.168.1.123</code></div><p class="small">示例 IP 要换成自己的。热点密码、家庭 Wi-Fi 密码、radxa 系统密码用途不同；中控使用最后一个。</p><div class="actions"><a class="btn primary" href="../console-guide.html#network">跟着图文查找 IP →</a></div><p class="done">正常结果：已知道机器人在家庭网络中的 IP，并记住自己设置的系统登录密码。</p><a class="step-next" href="#connect">下一步：连接机器人中控 ↓</a></section>'''
start+='<section class="chapter" id="connect"><div class="chapter-head"><span class="number">03</span><h2>在电脑启动机器人中控</h2></div>'+actions(link(CONSOLE,'下载机器人中控 R17 V167','btn primary'),link('../console-guide.html#connect','看实际连接界面','btn'))+'<ol><li>完整解压 ZIP：Windows 运行 <code>start.cmd</code>，macOS 运行 <code>start.command</code>。</li><li>在本地打开的中控页面，填写 <code>radxa@自己的IP</code> 和配网时设置的系统登录密码，点击连接。</li><li>等待启动步骤 1/4～4/4 完成，查看关节与 IMU 反馈。</li><li>R1 镜像预装 control.40；使用 V167 的“系统维护 → 随包固件”更新到配套 control.43，安装后再核对运行版本。</li></ol><div class="note-box"><p>仓库的中控在线演示用于熟悉界面。连接实体鸭子时，使用下载并启动的本地机器人中控。</p></div><p class="done">正常结果：本地中控连接成功，15 个关节与 IMU 反馈正常，实际运行版本已确认。</p><details><summary>已经刷过系统，只想升级？</summary><p>已有系统不用为了更新中控重新刷卡。先核对实际版本，按中控的系统维护步骤升级配套固件，保留并重新核对本机标定。</p></details><a class="step-next" href="#calibration">下一步：本机标定 ↓</a></section>'
start+='''<section class="chapter" id="calibration"><div class="chapter-head"><span class="number">04</span><h2>先标定这只鸭子，再运行模型</h2></div><p>配套模型可以直接使用；关节零位、方向、限位和 IMU 安装方向需要按自己这只鸭子核对。</p><ol><li>在标定模式下逐个核对关节 ID：右腿 10–14，左腿 20–24，头颈 30–34。</li><li>对照 3D 的独立零位与正向参考，核对并保存每个关节的本机标定。</li><li>缓慢前后、左右倾斜实物，对照实测 3D 检查 IMU 方向，再保存自己的安装标定。</li></ol><div class="actions"><a class="btn primary" href="../console-guide.html#calibration">逐关节标定图文 →</a><a class="btn" href="../console-guide.html#imu">IMU 核对图文 →</a></div><p class="done">正常结果：15 个关节已逐一核对，屏幕姿态与实物倾斜方向对应。</p><details><summary>标定参考按钮会让实物运动吗？</summary><p>3D 的“零位 0°”“HOME 站姿”“0 → +10°”只改变屏幕参考模型。已装配机器人不要用“全部顺序回到 2048”代替逐轴标定。</p></details><a class="step-next" href="#home">下一步：检查 HOME ↓</a></section>'''
start+='''<section class="chapter" id="home"><div class="chapter-head"><span class="number">05</span><h2>先回到 HOME，观察站姿</h2></div><ol><li>确认标定完成、反馈正常，扶稳机器人并松开摇杆。</li><li>切到运动模式，等待启动完成。使用实体手柄时，首次按 <strong>Start</strong> 回 HOME。</li><li>等站姿到位，核对左右腿、头部姿态和机械活动范围；姿势异常时先回到标定与装配核对。</li></ol><div class="actions"><a class="btn primary" href="../console-guide.html#control">查看 HOME 与手柄操作 →</a></div><p class="done">正常结果：鸭子完成 HOME 回位，站姿与装配、标定相符。</p><a class="step-next" href="#walk">下一步：保持与第一次行走 ↓</a></section>'''
start+='''<section class="chapter" id="walk"><div class="chapter-head"><span class="number">06</span><h2>启用现成模型，先保持，再迈步</h2></div><ol><li>HOME 到位后，再按 <strong>Start</strong> 启用策略，先观察零速度保持。</li><li>保持正常后，用左摇杆小幅输入尝试前后行走；右摇杆左右控制转向。</li><li>松开摇杆回到零速度保持；Start 关闭策略并回 HOME。需要卸力时，扶稳后短按并松开 Select。</li></ol><div class="note-box"><p>实体手柄接入时，网页输入会暂停。先选定一种操控方式，再跟随对应的中控说明操作。</p></div><p class="done">完成标准：能使用配套模型保持、迈步，并能回 HOME 或按需卸力。</p><div class="actions"><a class="btn primary" href="../console-guide.html#buttons">继续看常用动作与按键 →</a><a class="btn" href="../console-guide.html#help">连接了却不走？按现象排查</a></div></section>'''+next_page(3)
(OUT/'start.html').write_text(shell('start.html','我要让鸭子走起来','Microduck 使用现成模型，从刷镜像、配网查 IP、连接中控、标定到 HOME 和第一次行走。',start,3))
print('Rendered 5 build pages from one price data source.')
